const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    // Define a polygon for the Pantanal biome in Brazil
    // Source for approximate coordinates: Based on common definitions of Pantanal
    const pantanal = ee.Geometry.Polygon(
      [[[-58.5, -22.5],
        [-58.5, -16.0],
        [-55.0, -16.0],
        [-55.0, -22.5],
        [-58.5, -22.5]]]);

    const targetDateStart = '2024-06-11';
    const targetDateEnd = '2024-06-12'; // To include the full day of June 11

    // 2. Data Acquisition & Check for Target Date
    const modisFires = ee.ImageCollection('MODIS/061/MCD14DL');

    const targetFires = modisFires
      .filterBounds(pantanal)
      .filterDate(targetDateStart, targetDateEnd);

    const targetFireCount = await targetFires.size().getInfo();

    if (targetFireCount === 0) {
      console.log(`No fire detections found for ${targetDateStart} in Pantanal.`);
      console.log('C1');
      return;
    }
    console.log(`Fire detections on ${targetDateStart}: ${targetFireCount}`);

    // 3. Data Acquisition & Check for Historical Junes (2000-2023)
    const historicalYears = ee.List.sequence(2000, 2023).getInfo();
    let maxHistoricalJuneCount = 0;
    let anyHistoricalDataFound = false;
    let allHistoricalEmpty = true;

    for (const year of historicalYears) {
      const juneStart = `${year}-06-01`;
      const juneEnd = `${year}-06-30`; // End of June
      const juneFires = modisFires
        .filterBounds(pantanal)
        .filterDate(juneStart, juneEnd);

      const juneFireCount = await juneFires.size().getInfo();
      console.log(`June ${year} Fire Detections: ${juneFireCount}`);

      if (juneFireCount > 0) {
        anyHistoricalDataFound = true;
        allHistoricalEmpty = false;
      }

      if (juneFireCount > maxHistoricalJuneCount) {
        maxHistoricalJuneCount = juneFireCount;
      }
    }

    if (!anyHistoricalDataFound && allHistoricalEmpty) {
      console.log('No historical fire data found for any June from 2000-2023 in Pantanal.');
      console.log('C1'); // All historical Junes are empty
      return;
    }

    console.log(`Max historical June fire detections (2000-2023): ${maxHistoricalJuneCount}`);

    // 4. Comparison and Final Answer
    if (targetFireCount === null || maxHistoricalJuneCount === null) {
      console.log('C3'); // Calculation failure if any count is null
      return;
    }

    if (targetFireCount > maxHistoricalJuneCount) {
      console.log('A'); // Yes
    } else {
      console.log('B'); // No
    }

  } catch (error) {
    console.error('Analysis failed:', error);
    if (error.message.includes('Invalid argument specified for ee.ImageCollection')) {
        console.log('D'); // Likely a collection or band name error
    } else if (error.message.includes('A band containing all null values was requested.')) {
        console.log('C3'); // Band may be empty or contain only nulls after filtering
    } else {
        console.log('D'); // Generic error for other issues like syntax or memory
    }
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

